public static VFXBuilderTextureRenderRequest paletteSwap(ResourceLocation writeLocation, LoadedDyePalettes dyePalettes, DyeColor outputColor) {
        if (outputColor.equals(DyeColor.WHITE)) {
            throw new IllegalArgumentException("Cannot swap dye palette from white to white!");
        }
        return paletteSwap(writeLocation, dyePalettes.get(DyeColor.WHITE), dyePalettes.get(outputColor));
    }

public static VFXBuilderTextureRenderRequest paletteSwap(ResourceLocation writeLocation, PaletteData input, PaletteData output) {
        var builder = new VFXBuilderTextureRenderRequest(writeLocation);
        builder.setShader(MalumShaders.PALETTE_SWAP);
        var data = UniformData.create();
        data.setUniform("InputPalette", input.bakeUniform());
        data.setUniform("OutputPalette", output.bakeUniform());
        builder.setUniforms(data.build());
        return builder;
    }

public VFXBuilderTextureRenderRequest setShader(ShaderHolder shader) {
        return setShader(shader.getShaderInstance());
    }

public VFXBuilderTextureRenderRequest setShader(ShaderInstance shader) {
        this.shader = shader;
        return this;
    }

public VFXBuilderTextureRenderRequest setUniforms(UniformData data) {
        this.data = data;
        return this;
    }

public VFXBuilderTextureRenderRequest setDrawnTexture(ResourceLocation drawnTexture) {
        this.drawnTexture = drawnTexture;
        return this;
    }

@Override
    public void drawTexture(LodestoneDynamicTexture texture, GuiGraphics guiGraphics) {
        var stack = guiGraphics.pose();
        RenderSystem.enableDepthTest();
        RenderSystem.depthMask(false);
        RenderSystem.enableBlend();
        data.setValues(shader);
        VFXBuilders.createScreen()
                .setPositionWithWidth(0, 0, texture.getWidth(), texture.getHeight())
                .setUV(0, 1, 1, 0)
                .setFormat(DefaultVertexFormat.POSITION_TEX_COLOR)
                .setShader(shader)
                .setTexture(drawnTexture)
                .blit(stack);
        if (shader instanceof ExtendedShaderInstance extendedShaderInstance) {
            extendedShaderInstance.applyUniformDefaults();
        }
        RenderSystem.disableDepthTest();
        RenderSystem.depthMask(true);
        RenderSystem.disableBlend();
    }

public static DynamicTextureRenderer create(DynamicTextureRenderRequest request) {
        return new DynamicTextureRenderer(request);
    }

private DynamicTextureRenderer(DynamicTextureRenderRequest request) {
        this.request = request;
    }

public DynamicTextureRenderer setTextureSize(int width, int height) {
        this.width = width;
        this.height = height;
        return this;
    }

public LodestoneDynamicTexture bakeTexture() {
        request.modify(this);
        var texture = DynamicTextureCache.pushTexture(request, this::createTexture);
        if (texture != null && isTicking) {
            texture.redraw();
        }

        return texture;
    }

private CompletableFuture<LodestoneDynamicTexture> createTexture(ResourceLocation key) {
        var nested = new CompletableFuture<LodestoneDynamicTexture>();
        RenderSystem.recordRenderCall(() -> {
            try {
                var texture = new LodestoneDynamicTexture(request, width, height, hScale, vScale);
                nested.complete(texture);
            } catch (Throwable t) {
                MalumMod.LOGGER.error("Failed to create dynamic texture for id {}", request.getWriteLocation(), t);
                nested.completeExceptionally(t);
            }
        });
        return nested;
    }

public static LodestoneDynamicTexture pushTexture(DynamicTextureRenderRequest request, Function<ResourceLocation, CompletableFuture<LodestoneDynamicTexture>> textureSupplier) {
        return pushTexture(request, textureSupplier, false);
    }

public static LodestoneDynamicTexture pushTexture(DynamicTextureRenderRequest request, Function<ResourceLocation, CompletableFuture<LodestoneDynamicTexture>> textureSupplier, boolean isTicking) {
        var key = request.getWriteLocation();
        var future = DynamicTextureCache.TEXTURES.computeIfAbsent(key, textureSupplier);
        if (!future.isDone()) {
            return null;
        }
        var texture = future.join();
        if (texture.isClosed()) {
            TEXTURES.remove(key);
            return null;
        }
        if (isTicking) {
            texture.redraw();
        }
        return texture;
    }

public LodestoneDynamicTexture(DynamicTextureRenderRequest request, int width, int height, float hScale, float vScale) {
        super(width, height, false);
        RenderSystem.assertOnRenderThread();
        this.request = request;
        this.width = width;
        this.height = height;
        this.hScale = hScale;
        this.vScale = vScale;

        Minecraft.getInstance().getTextureManager().register(request.getWriteLocation(), this);
    }

@Override
    public int getId() {
        if (closed) {
            return -1;
        }
        RenderSystem.assertOnRenderThreadOrInit();
        if (renderTarget == null) {
            var pixels = getPixels();
            int w = pixels.getWidth();
            int h = pixels.getHeight();
            renderTarget = new TextureTarget(w, h, true, ON_OSX);
        }
        return renderTarget.getColorTextureId();
    }

public void bind(int id) {
        if (closed) {
            return;
        }
        RenderSystem.setShaderTexture(id, renderTarget.getColorTextureId());
    }

@Override
    public void bind() {
        if (closed) {
            return;
        }
        super.bind();
    }

public boolean isClosed() {
        return closed;
    }

public void redraw() {
        needsUpdate = true;
    }

@Override
    public void tick() {
        if (closed) {
            return;
        }
        if (needsUpdate) {
            bakeRequest();
            needsUpdate = false;
        }
    }

public void bakeRequest() {
        executeOnRenderThread(() -> {
            bind();
            bakeContents();
        });
    }

private void bakeContents() {
        var oldProjMat = RenderSystem.getProjectionMatrix();
        var newProjMat = getProjectionMatrix();
        var minecraft = Minecraft.getInstance();
        var guiGraphics = new GuiGraphics(minecraft, minecraft.renderBuffers().bufferSource());

        var modelViewStack = RenderSystem.getModelViewStack();
        modelViewStack.pushMatrix();
        modelViewStack.set(getModelViewMatrix());
        RenderSystem.applyModelViewMatrix();

        RenderSystem.setProjectionMatrix(newProjMat, VertexSorting.ORTHOGRAPHIC_Z);

        renderTarget.setClearColor(0, 0, 0, 0);
        renderTarget.clear(Minecraft.ON_OSX);
        renderTarget.bindWrite(true);

        request.drawTexture(this, guiGraphics);


        renderTarget.unbindWrite();
        minecraft.getMainRenderTarget().bindWrite(true);

        modelViewStack.popMatrix();
        RenderSystem.applyModelViewMatrix();
        RenderSystem.setProjectionMatrix(oldProjMat, VertexSorting.ORTHOGRAPHIC_Z);
    }

private Matrix4f getProjectionMatrix() {
        return new Matrix4f().ortho(
                0, width/hScale,
                height/vScale, 0,
                0.05f, 2000.0f
        );
    }

private Matrix4f getModelViewMatrix() {
        Matrix4f matrix4f = new Matrix4f();
        matrix4f.identity();
        matrix4f.translate(0, 0, -2000);
        return matrix4f;
    }

private static void executeOnRenderThread(RenderCall call) {
        if (RenderSystem.isOnRenderThreadOrInit()) {
            call.execute();
            return;
        }
        RenderSystem.recordRenderCall(call);
    }

@Override
    public void releaseId() {
        if (!closed) {
            var writeLocation = request.getWriteLocation();
            Minecraft.getInstance().getTextureManager().release(writeLocation);
            executeOnRenderThread(() -> {
                if (renderTarget != null) {
                    renderTarget.destroyBuffers();
                    renderTarget = null;
                }
            });
            closed = true;
        }
    }

protected DynamicTextureRenderRequest(ResourceLocation writeLocation) {
        this.writeLocation = writeLocation.withPath(p -> p.endsWith(".png") ? p : p + ".png").withPrefix("generated/");
    }

public ResourceLocation getWriteLocation() {
        return writeLocation;
    }

public PaletteData(List<Integer> colors) {
        this.colors = ImmutableList.copyOf(colors);
    }

public float[] bakeUniform() {
        float[] array = new float[48];
        Arrays.fill(array, -1);
        for (int i = 0; i < colors.size(); i++) {
            var index = i * 3;
            var color = colors.get(i);
            int red = FastColor.ABGR32.red(color);
            int green = FastColor.ABGR32.green(color);
            int blue = FastColor.ABGR32.blue(color);
            array[index] = red / 255f;
            array[index+1] = green / 255f;
            array[index+2] = blue / 255f;
        }
        return array;
    }

public PaletteData get(DyeColor color) {
        return palettes.get(color);
    }

@Override
    public void reload(ResourceManager manager) {
        super.reload(manager);
        palettes.clear();
        if (image != null) {
            var dyes = DyeColor.values();
            for (int i = 0; i < dyes.length; i++) {
                if (i > 15) {
                    //TODO: Dye Depot Compat
                    break;
                }
                int x = 1;
                int y = i * 2;
                palettes.put(dyes[i], readPalette(image, x, y));
            }
        }
    }

public PaletteData readPalette(NativeImage image, int x, int y) {
        List<Integer> colors = new ArrayList<>();
        for (int i = 0; i < colorAmount; i++) {
            int rgba = image.getPixelRGBA(x + i, y);
            colors.add(rgba);
        }
        return new PaletteData(colors);
    }

public void reload(ResourceManager manager) {
		var optional = manager.getResource(readLocation);

		if (optional.isEmpty()) {
			return;
		}

		try (var is = optional.get().open()) {
			image = NativeImage.read(NativeImage.Format.RGBA, is);

		} catch (IOException e) {
            throw new RuntimeException(e);
        }
    }

public static void register(RegisterClientReloadListenersEvent event) {
		event.registerReloadListener(DATA);
	}

public <T extends LoadedTexture> T register(T texture) {
		textures.add(texture);
		return texture;
	}

@Override
	public void onResourceManagerReload(ResourceManager manager) {
		for (LoadedTexture texture : textures) {
			texture.reload(manager);
		}
	}

@SubscribeEvent
    public static void registerListeners(RegisterClientReloadListenersEvent event) {
        TextureLoaderReloadListener.register(event);
    }

@SubscribeEvent
    public static void shaderRegistry(RegisterShadersEvent event) {
        SHADERS.init(event);
    }

@Override
    public void render(T blockEntity, float partialTicks, PoseStack poseStack, MultiBufferSource bufferIn, int combinedLightIn, int combinedOverlayIn) {
        var blockState = blockEntity.getBlockState();
        var pos = blockEntity.getBlockPos();

        var type = blockState.getValue(SoulwovenBannerBlock.BANNER_TYPE);
        var direction = type.direction.getAxis().isVertical() ? type.equals(SoulwovenBannerBlock.BannerType.HANGING_Z) ? Direction.NORTH : Direction.WEST : type.direction;
        float sway = ((float) Math.floorMod((pos.getX() * 7L + pos.getY() * 9L + pos.getZ() * 13L) + blockEntity.getLevel().getGameTime(), 100L) + partialTicks) / 100.0F;
        float swayRotation = (0.01F * Mth.cos((float) (Math.PI * 2) * sway)) * (float) Math.PI;

        poseStack.pushPose();
        poseStack.translate(0.5f, 0.5f, 0.5f);
        poseStack.mulPose(Axis.YN.rotationDegrees(direction.toYRot()));
        poseStack.translate(-0.5f, -0.5f, -0.5f);
        if (type.direction.getAxis().isHorizontal()) {
            poseStack.translate(0, -0.25f, 0.0625f);
            swayRotation -= 0.0125f;
        } else {
            poseStack.translate(0, 0, 0.5f);
            swayRotation = swayRotation - 0.0157f;
        }
        poseStack.translate(0, 1f, 0);
        poseStack.mulPose(Axis.XP.rotation(swayRotation));
        float xStart = 0;
        float xEnd = 1;
        float yStart = -2;
        float yEnd = 0;

        var vertices = new Vector3f[]{new Vector3f(xEnd, yStart, 0), new Vector3f(xStart, yStart, 0), new Vector3f(xStart, yEnd, 0), new Vector3f(xEnd, yEnd, 0)};
        var builder = VFXBuilders.createWorld().setLightLevel(pos);

        renderBanner(blockEntity, poseStack, builder, vertices);
        poseStack.popPose();
    }

public FancyBannerBlockEntity(BlockPos pos, BlockState state) {
        super(MalumBlockEntities.FANCY_BANNER.get(), pos, state);
        color = ((FancyBannerBlock)state.getBlock()).getColor();
    }

