public static final DrawingFunction NEW_ENTITY = (builder, posX, posY, posZ, normX, normY, normZ, packedLight, r, g, b, a, u, v, overlay) -> {
	builder.addVertex(posX, posY, posZ)
	        .setColor(r, g, b, a)
	        .setUv(u, v)
	        .setOverlay(overlay)
	        .setLight(packedLight)
	        .setNormal(normX, normY, normZ);
};

